///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function (_tpCd) {
    scwin.selFrm = $c.util.getComponent('corpDisclsChrgForm' + _tpCd);
    const zipSearchURL = '/jldinf90009/jldinf90009.xml';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin.setZipCode_recv(await $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(zipSearchURL), { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { selFrm: (typeof scwin.selFrm !== 'undefined' ? scwin.selFrm : undefined) })));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent("ipt_locZipcd").setValue(_zipCode);
    $c.util.getComponent("ipt_locAddr").setValue(_address);
    $c.util.getComponent('dma_ModifyReq').set('applYn', "Y");
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _doFlag _doFlag
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_doFlag, _tpCd) {
    // TODO Stage2: $c.cm.fn_* 정의 없음(pcc/fil 미반입 · 치환 방향 미결) — fn_CheckDateGn, fn_ChkZipCd
    const frm = $c.util.getComponent('corpDisclsChrgForm' + _tpCd);
    if (_doFlag === 'insert') {
        if (await scwin.checkRequired($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_telNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_telNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_telNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_chrgInnrNo')))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('slc_cellphoneNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_faxNo1')) || await scwin.checkRequired($c.util.getComponent('ipt_faxNo2')) || await scwin.checkRequired($c.util.getComponent('ipt_faxNo3'))) {
        return;
    }
    if (!(scwin.isNumberInput($c.util.getComponent('ipt_faxNo1')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo2')) && scwin.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_email1')) || await scwin.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (_doFlag === 'insert') {
        if (await scwin.checkRequired($c.util.getComponent('ipt_chrgDesignYear')) || await scwin.checkRequired($c.util.getComponent('ipt_chrgDesignMonth')) || await scwin.checkRequired($c.util.getComponent('ipt_chrgDesignDay'))) {
            return;
        }
        if (!$c.cm.fn_CheckDateGn($c.util.getComponent('ipt_chrgDesignYear'), $c.util.getComponent('ipt_chrgDesignMonth'), $c.util.getComponent('ipt_chrgDesignDay'), false)) {
            return;
        }
        if ($c.util.getComponent('dma_ModifyReq').get('disclsProfsYn') === '') {
            $c.util.getComponent('dma_ModifyReq').set('disclsProfsYn', '-');
        }
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_locZipcd'))) {
        return;
    }
    if (!($c.cm.fn_ChkZipCd($c.util.getComponent('ipt_locZipcd')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return;
    }
    if (await scwin.checkRequired($c.util.getComponent('ipt_locAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_locAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_locDtlAddr'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('telNo', $c.util.getComponent('ipt_telNo1').getValue()+ '-' + $c.util.getComponent('ipt_telNo2').getValue()+ '-' + $c.util.getComponent('ipt_telNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('cellphoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('faxNo', $c.util.getComponent('ipt_faxNo1').getValue()+ '-' + $c.util.getComponent('ipt_faxNo2').getValue()+ '-' + $c.util.getComponent('ipt_faxNo3').getValue());
    $c.util.getComponent('dma_ModifyReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    $c.util.getComponent('dma_ModifyReq').set('chrgDesignDd', $c.util.getComponent('ipt_chrgDesignYear').getValue()+ $c.util.getComponent('ipt_chrgDesignMonth').getValue()+ $c.util.getComponent('ipt_chrgDesignDay').getValue());
    if (!$c.str.isEmail($c.util.getComponent('dma_ModifyReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_ModifyReq').set('doFlag', _doFlag);
    $c.util.getComponent('dma_ModifyReq').set('method', 'modifyMktOrganizerDisclsChrg');
    frm.action = 'corpDiscls.do';
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name deleteModifyReq
 * @description delete Modify Req 처리
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteModifyReq = async function (_tpCd) {
    if (await $c.win.confirm('정말 삭제하시겠습니까?')) {
        const frm = $c.util.getComponent('corpDisclsChrgForm' + _tpCd);
        $c.util.getComponent('dma_ModifyReq').set('doFlag', 'delete');
        $c.util.getComponent('dma_ModifyReq').set('method', 'modifyMktOrganizerDisclsChrg');
        frm.action = 'corpDiscls.do';
        await scwin.tx_fn_Delete();
    }
};

/**
